import {
  accessSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from 'fs';
import { join } from 'path';

export namespace DB {
  // Types for our persistence layer
  export interface MemoryItem {
    id: string;
    memory: string;
    createdAt: string;
    embedding: number[];
  }

  export interface PersistenceData {
    memories: DB.MemoryItem[];
  }
}

// File path for storing the data
const DATA_FILE_PATH = join(
  process.cwd(),
  'data',
  'memories.local.json',
);

export const generateId = () => {
  return Math.random().toString(36).substring(2, 10);
};

/**
 * Ensure the data directory exists
 */
function ensureDataDirectory(): void {
  const dataDir = join(process.cwd(), 'data');
  try {
    accessSync(dataDir);
  } catch {
    mkdirSync(dataDir, { recursive: true });
  }
}

function loadDB(): DB.PersistenceData {
  try {
    ensureDataDirectory();
    const data = readFileSync(DATA_FILE_PATH, 'utf-8');
    return JSON.parse(data) as DB.PersistenceData;
  } catch (error) {
    return { memories: [] };
  }
}

/**
 * Load all chats from the JSON file
 */
export function loadMemories(): DB.MemoryItem[] {
  try {
    ensureDataDirectory();
    const data = readFileSync(DATA_FILE_PATH, 'utf-8');
    const parsed: DB.PersistenceData = JSON.parse(data);
    return parsed.memories || [];
  } catch (error) {
    // If file doesn't exist or is invalid, return empty array
    return [];
  }
}

/**
 * Save all chats to the JSON file
 */
export function saveMemories(memories: DB.MemoryItem[]): void {
  const data = loadDB();
  data.memories = [...data.memories, ...memories];

  writeFileSync(
    DATA_FILE_PATH,
    JSON.stringify(data, null, 2),
    'utf-8',
  );
}

export function updateMemory(
  memoryId: string,
  memory: Omit<DB.MemoryItem, 'id'>,
): boolean {
  const data = loadDB();
  data.memories = data.memories.map((m) =>
    m.id === memoryId ? { ...m, ...memory } : m,
  );

  writeFileSync(
    DATA_FILE_PATH,
    JSON.stringify(data, null, 2),
    'utf-8',
  );

  return true;
}

export function deleteMemory(memoryId: string): boolean {
  const data = loadDB();
  data.memories = data.memories.filter((m) => m.id !== memoryId);

  writeFileSync(
    DATA_FILE_PATH,
    JSON.stringify(data, null, 2),
    'utf-8',
  );

  return true;
}

import { google } from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStreamResponse,
  streamText,
  type ModelMessage,
  type UIMessage,
} from 'ai';

export const POST = async (req: Request): Promise<Response> => {
  const body = await req.json();

  // NOTE: We receive the messages from the client.
  const messages: UIMessage[] = body.messages;

  // NOTE: We convert the messages to the format
  // expected by the model.
  const modelMessages: ModelMessage[] =
    convertToModelMessages(messages);

  // NOTE: We stream the text from the model.
  const streamTextResult = streamText({
    model: google('gemini-2.0-flash'),
    messages: modelMessages,
  });

  // NOTE: We convert the stream to the format
  // expected by the client.
  const stream = streamTextResult.toUIMessageStream();

  // NOTE: We create the response for the client.
  return createUIMessageStreamResponse({
    stream,
  });
};

import { google } from '@ai-sdk/google';
import { cosineSimilarity, embed } from 'ai';
import type { DB } from './memory-persistence.ts';

const myEmbeddingModel = google.textEmbeddingModel(
  'text-embedding-004',
);

export const searchMemoriesViaEmbeddings = async (
  memories: DB.MemoryItem[],
  query: string,
) => {
  const queryEmbedding = await embed({
    model: myEmbeddingModel,
    value: query,
  }).then((result) => result.embedding);

  const scores = memories.map((memory) => {
    return {
      score: cosineSimilarity(queryEmbedding, memory.embedding),
      memory,
    };
  });

  return scores.sort((a, b) => b.score - a.score);
};

export const EMBED_CACHE_KEY = 'memories-google';

export const embedMemory = async (memory: string) => {
  return embed({
    model: myEmbeddingModel,
    value: memory,
  }).then((result) => result.embedding);
};

import type { ModelMessage } from 'ai';

export const formatModelMessages = (
  messages: ModelMessage[],
) => {
  return messages
    .map((message) => {
      let content: string;

      if (typeof message.content === 'string') {
        content = message.content;
      } else {
        content = message.content
          .map((part) => {
            if (part.type === 'text') {
              return part.text;
            }

            if (part.type === 'tool-call') {
              return [
                `Tool call: ${part.toolName}`,
                `Input: ${JSON.stringify(part.input)}`,
              ].join('\n');
            }

            if (part.type === 'tool-result') {
              return [
                `Tool result: ${part.toolName}`,
                `Output: ${JSON.stringify(part.output)}`,
              ].join('\n');
            }
          })
          .filter((part) => part !== undefined)
          .join('\n\n');
      }

      return [
        message.role === 'user' ? 'User:' : 'Assistant:',
        content,
      ].join('\n\n');
    })
    .join('\n\n');
};

import type { DB } from './memory-persistence.ts';

const RRF_K = 60;

export function reciprocalRankFusion(
  rankings: { memory: DB.MemoryItem; score: number }[][],
): { memory: DB.MemoryItem; score: number }[] {
  const rrfScores = new Map<string, number>();
  const documentMap = new Map<string, DB.MemoryItem>();

  // Process each ranking list
  rankings.forEach((ranking) => {
    ranking.forEach((doc, rank) => {
      // Get current RRF score for this document
      const currentScore = rrfScores.get(doc.memory.id) || 0;

      // Add contribution from this ranking list
      const contribution = 1 / (RRF_K + rank);
      rrfScores.set(doc.memory.id, currentScore + contribution);

      // Store document reference
      documentMap.set(doc.memory.id, doc.memory);
    });
  });

  // Sort by RRF score (descending)
  return Array.from(rrfScores.entries())
    .sort(([, scoreA], [, scoreB]) => scoreB - scoreA)
    .map(([memoryId, score]) => ({
      memory: documentMap.get(memoryId)!,
      score,
    }));
}

